import { useEffect, useState } from 'react';
import { cn } from '@/lib/cn';
import { usePrefersReducedMotion } from '@/lib/hooks';
import { useTheme } from '@/lib/theme';
// Bundled (hashed under /assets/) rather than linked from /brand/, so the logo loads wherever the app
// does. WebP at twice the on-screen size, generated by scripts/brand.py (keep the sizes in step).
import mark72 from '@/assets/brand/mark-72.webp';
import mark112 from '@/assets/brand/mark-112.webp';
import mark224 from '@/assets/brand/mark-224.webp';
import wordmarkImg from '@/assets/brand/wordmark-520.webp';
import wordmarkInkImg from '@/assets/brand/wordmark-ink-520.webp';
import wordtypeImg from '@/assets/brand/wordtype-48.webp';
import wordtypeInkImg from '@/assets/brand/wordtype-ink-48.webp';

/** Mark variants by pixel width, smallest first. */
const MARKS: readonly [number, string][] = [
  [72, mark72],
  [112, mark112],
  [224, mark224],
];

/** The smallest mark that is at least twice `size` (sharp on 2x screens), else the largest. */
function markFor(size: number): string {
  return (MARKS.find(([w]) => w >= size * 2) ?? MARKS[MARKS.length - 1])[1];
}

/** The Schema mark (generated by scripts/brand.py). */
export function Mark({ size = 32, className, alt = '' }: { size?: number; className?: string; alt?: string }) {
  const src = markFor(size);
  return (
    <img
      src={src}
      width={size}
      height={size}
      alt={alt}
      aria-hidden={alt ? undefined : true}
      decoding="async"
      draggable={false}
      className={cn('select-none', className)}
    />
  );
}

/** Mark + "Schema" wordmark image; switches to the ink variant on light surfaces. */
export function Wordmark({
  className,
  forceDark,
  width = 220,
}: {
  className?: string;
  forceDark?: boolean;
  width?: number;
}) {
  const { theme } = useTheme();
  const dark = forceDark || theme === 'dark';
  return (
    <img
      src={dark ? wordmarkImg : wordmarkInkImg}
      alt="Schema"
      width={width}
      height={Math.round((width * 524) / 644)}
      draggable={false}
      className={cn('select-none', className)}
    />
  );
}

/** The "Schema" text alone, in the brand typeface (for horizontal lockups). */
export function Wordtype({ height = 18, className }: { height?: number; className?: string }) {
  const { theme } = useTheme();
  return (
    <img
      src={theme === 'dark' ? wordtypeImg : wordtypeInkImg}
      alt="Schema"
      height={height}
      width={Math.round((height * 644) / 127)}
      draggable={false}
      className={cn('select-none', className)}
    />
  );
}

/**
 * Cold-load splash (SPEC §9.2): centered mark with a soft gradient glow on ink-950.
 * Stays at least `minMs` and fades out; skipped entirely under reduced motion.
 */
export function Splash({ done, minMs = 400, onGone }: { done: boolean; minMs?: number; onGone: () => void }) {
  const reduced = usePrefersReducedMotion();
  const [elapsed, setElapsed] = useState(false);
  const [leaving, setLeaving] = useState(false);

  useEffect(() => {
    const t = setTimeout(() => setElapsed(true), reduced ? 0 : minMs);
    return () => clearTimeout(t);
  }, [minMs, reduced]);

  useEffect(() => {
    if (!done || !elapsed) return;
    if (reduced) {
      onGone();
      return;
    }
    setLeaving(true);
    const t = setTimeout(onGone, 240);
    return () => clearTimeout(t);
  }, [done, elapsed, reduced, onGone]);

  if (reduced && done) return null;

  return (
    <div
      className={cn(
        'fixed inset-0 z-[200] flex items-center justify-center bg-[#0F1216]',
        leaving ? 'animate-fade-out' : 'animate-fade-in',
      )}
      role="status"
      aria-label="Loading Schema"
    >
      <div className="relative flex items-center justify-center">
        <div
          className="absolute h-56 w-56 rounded-full bg-brand-gradient opacity-30 blur-3xl animate-glow"
          aria-hidden
        />
        <Mark size={112} className="relative drop-shadow-[0_0_24px_rgba(29,198,239,0.35)]" />
      </div>
    </div>
  );
}
